function getStrength(utr) {
  if (!utr || utr.length < 5) return null;
  const t = utr.trim().toUpperCase();
  const uniqueRatio = new Set(t.split("")).size / t.length;
  const bankPfx = ["HDFC", "ICIC", "SBIN", "AXIS", "PYTM", "YESB", "KOTAK", "GPAY", "NEFT", "RTGS", "IMPS"];
