  const hasMixed = /[A-Z]/.test(t) && /\d/.test(t);
  if (uniqueRatio > 0.6 && hasMixed && t.length >= 12) return {
    label: "Strong",
    color: "#16a34a",
    pct: 90
  };
  if (hasPrefix || hasMixed && t.length >= 10) return {
    label: "Good",
    color: "#2563eb",
    pct: 65
  };
  if (uniqueRatio < 0.25) return {
    label: "Weak",
    color: "#dc2626",
    pct: 20
  };
  return {
    label: "Fair",
    color: "#d97706",
    pct: 45
  };
}

