  };
  const seq = "01234567890123456789012345";
  if (seq.includes(t)) return {
    valid: false,
    msg: "❌ Sequential digits are not a valid UTR."
  };
  for (const p of [/^test/i, /^fake/i, /^dummy/i, /^sample/i, /^1234/, /^0000/, /^9999/]) if (p.test(t)) return {
    valid: false,
    msg: "❌ Invalid UTR — enter the real one from your app."
  };
  return {
    valid: true
  };
}

